import 'package:smart_coach_new/features/configuration/train_configuration/data/models/train_list_response.dart';import 'package:smart_coach_new/features/drop_down_value/data/models/role_list_response.dart';import 'package:smart_coach_new/features/user_management/domain/entities/pending_users_request.dart';import 'package:smart_coach_new/features/user_management/domain/entities/user_entity.dart';abstract class UserManagementState {  final List<UserEntity> users;  final List<UserEntity> selectedUsers;  final PendingUsersRequest? request;  const UserManagementState({    this.users = const [],    this.selectedUsers = const [],    this.request,  });}class UserManagementInitial extends UserManagementState {  const UserManagementInitial() : super();}class UserManagementLoading extends UserManagementState {  const UserManagementLoading({    super.users,    super.selectedUsers,    super.request,  });}class UserManagementSuccess extends UserManagementState {  const UserManagementSuccess({    required super.users,    required super.selectedUsers,    required super.request,  });  UserManagementSuccess copyWith({    List<UserEntity>? users,    List<UserEntity>? selectedUsers,    PendingUsersRequest? request,  }) {    return UserManagementSuccess(      users: users ?? this.users,      selectedUsers: selectedUsers ?? this.selectedUsers,      request: request ?? this.request,    );  }}class UserManagementFailure extends UserManagementState {  final String message;  const UserManagementFailure(    this.message, {    super.users,    super.selectedUsers,    super.request,  });}class UserManagementActionInProgress extends UserManagementState {  const UserManagementActionInProgress({    super.users,    super.selectedUsers,    super.request,  });}class UserManagementActionSuccess extends UserManagementState {  final String message;  const UserManagementActionSuccess(    this.message, {    super.users,    super.selectedUsers,    super.request,  });}class LoadTrainsSuccess extends UserManagementState {  final List<TrainItem>? trains;  final List<RoleItem>? roles;  const LoadTrainsSuccess(    this.trains,    this.roles, {    super.users,    super.selectedUsers,    super.request,  });}class LoadRolesSuccess extends UserManagementState {  final List<RoleItem>? items;  const LoadRolesSuccess(    this.items, {    super.users,    super.selectedUsers,    super.request,  });}